mutation CreatePost($input: CreatePostInput!) {
  createPost(input: $input) {
        __typename
    ... on PostActionSuccess {
      post {
        id
        status
      }
    }
    ... on NotFoundError {
      message
    }
    ... on UnauthorizedError {
      message
    }
    ... on UnexpectedError {
      message
    }
    ... on RestProxyError {
      message
    }
    ... on LimitReachedError {
      message
    }
    ... on InvalidInputError {
      message
    }
  }
}
